CREATE TABLE anon.aggregated_store (entity_key String, event_date Date, unique_users AggregateFunction(uniq, UInt64), latency_quantiles AggregateFunction(quantiles(0.5, 0.9), Float64), total_bytes SimpleAggregateFunction(sum, UInt64), last_seen SimpleAggregateFunction(max, DateTime), items Nested(item_id UInt64, item_name String, item_price Float64)) ENGINE = AggregatingMergeTree PARTITION BY toYYYYMM(event_date) ORDER BY (entity_key, event_date)